\subsection{Training objective}
Training preserves recursive identities across frames. Existing tracks inherit their ground-truth identities through cross-frame target alignment (CTA), while Hungarian assignment is used only to match unmatched birth candidates to unmatched targets during training. The discrete assignment is detached and never used at inference. Losses are computed per supervised frame and averaged across valid rollout frames. Here $\operatorname{BCE}(\ell,y)$ denotes binary cross-entropy with logits.

\textbf{Set loss.} Let $\mathcal M_t$ be matched prediction--target pairs and $\mathcal C_t$ all valid existing/birth candidates. Candidate $k$ predicts position $\hat p_k$, logit $\ell_k$, and label $y_k\in\{0,1\}$; $p_n^*$ is the matched target position:
\begin{equation}
\mathcal L_{\rm set}=\frac{1}{|\mathcal M_t|}\!\sum_{(k,n)\in\mathcal M_t}\frac12\|\hat p_k-p_n^*\|_1
+\frac{1}{|\mathcal C_t|}\!\sum_{k\in\mathcal C_t}\operatorname{BCE}(\ell_k,y_k).
\label{eq:setloss}
\end{equation}
An empty matched set contributes zero localization loss.

\textbf{Probabilistic set-risk surrogate.} Reusing the detached CTA/Hungarian matching, define $\pi_k=\sigma(\ell_k)$, cutoff $c_{\rm risk}$, $d_c(k,n)=\min(\|\hat p_k-p_n^*\|_2,c_{\rm risk})$, and unmatched prediction/truth sets $\mathcal U_b,\mathcal V_b$:
\begin{align}
\mathcal L_{\rm risk}=\frac1B\sum_b\Bigg[&\sum_{(k,n)\in\mathcal M_b}
\left(\pi_k d_c(k,n)+(1-\pi_k)\frac {c_{\rm risk}}2\right)\nonumber\\
&+\sum_{k\in\mathcal U_b}\pi_k\frac {c_{\rm risk}}2+|\mathcal V_b|\frac {c_{\rm risk}}2\Bigg].
\label{eq:risk}
\end{align}
The matching is treated as fixed supervision rather than recomputed to minimize this risk. Its coefficient $\rho$ follows the curriculum in Sec.~\ref{sec:experiments}.


\textbf{Association and birth losses.} Simulator identities define the correct PAIR, MISS, and UNCLAIMED event sets $E_p,E_m,E_u$. With event weights $w_p,w_m,w_u$ and $Z_E$ equal to the sum of weights of event types present in the frame,
\begin{align}
\mathcal L_{\rm assoc}=-\frac1{Z_E}\Bigg[&\frac{w_p}{|E_p|}\sum_{(i,j)\in E_p}\log A_{ij}
+\frac{w_m}{|E_m|}\sum_{i\in E_m}\log A_{i\varnothing}\nonumber\\
&+\frac{w_u}{|E_u|}\sum_{j\in E_u}\log A_{\varnothing j}\Bigg].
\label{eq:assocloss}
\end{align}
Here, absent event types are omitted together with their weight. For birth, when both classes are present,
$\mathcal B(p,y)=-\tfrac12[\operatorname{mean}_{y=1}\log p+\operatorname{mean}_{y=0}\log(1-p)]$;
if only one class is present, $\mathcal B$ is the corresponding class mean. Then
\begin{equation}
\mathcal L_{\rm birth}=\mathcal B(\{u_j\},\{y_j^{\rm tgt}\})+\mathcal B(\{\pi_j^{\rm new}\},\{y_j^{\rm new}\}).
\label{eq:birthloss}
\end{equation}

\textbf{Lifecycle and cardinality.} For active slots $\mathcal A_t$, $y_i^{\rm alive}$ indicates current truth existence and $y_i^{\rm det}$ current detection; live-but-missed tracks use $\omega_i=1+\lambda_{\rm miss}\mathbf1[y_i^{\rm alive}=1,y_i^{\rm det}=0]$. For $\mathcal S_t\subseteq\mathcal A_t$ that existed at $t-1$, $y_i^S$ is one-step survival. With $p_i^S=\sigma(\operatorname{logit}(p_0^S)+\Delta s_i)$, $\ell_i^{\rm exist}=\operatorname{logit}r_i^+$, $\ell_i^S=\operatorname{logit}p_i^S$, and $W_t=\sum_{i\in\mathcal A_t}\omega_i$,
\begin{equation}
\begin{array}{@{}l@{\;}c@{\;}l@{}}
\mathcal L_{\rm exist} & = & \displaystyle \frac1{W_t}\sum_{i\in\mathcal A_t}
\omega_i\operatorname{BCE}(\ell_i^{\rm exist},y_i^{\rm alive}),\\[2pt]
\mathcal L_{\rm surv} & = & \displaystyle \frac1{|\mathcal S_t|}\sum_{i\in\mathcal S_t}
\operatorname{BCE}(\ell_i^S,y_i^S),\\[2pt]
\hat N_t & = & \displaystyle \sum_i m_i^{\rm ex}r_i^+ +\sum_jm_j^{\rm b}\pi_j^{\rm new},\\[2pt]
\mathcal L_{\rm card} & = & \operatorname{SmoothL1}(\hat N_t,N_t^*).
\end{array}
\label{eq:lifecycleloss}
\end{equation}
where $m^{\rm ex},m^{\rm b}$ are validity masks and $N_t^*$ is the true cardinality. Empty active/survival sets skip the corresponding term. The complete objective is
\begin{align}
\mathcal L={}&\lambda_{\rm set}\mathcal L_{\rm set}+\lambda_{\rm risk}\rho\mathcal L_{\rm risk}
+\lambda_{\rm assoc}\mathcal L_{\rm assoc}+\lambda_{\rm birth}\mathcal L_{\rm birth}\nonumber\\
&+\lambda_{\rm exist}\mathcal L_{\rm exist}+\lambda_{\rm surv}\mathcal L_{\rm surv}
+\lambda_{\rm card}\mathcal L_{\rm card}.
\label{eq:total}
\end{align}
We use $c_{\rm risk}=2$, $(w_p,w_m,w_u)=(2,1,1)$, and
$\lambda_{\rm miss}=2$. The loss weights
$(\lambda_{\rm set},\lambda_{\rm risk},\lambda_{\rm assoc},
\lambda_{\rm birth},\lambda_{\rm exist},\lambda_{\rm surv},
\lambda_{\rm card})$ are $(1,.1,1,.5,.35,.25,.03)$,
with $\rho$ ramped over steps 4k--6k.

